    double est = k / theta;
    double lb = BinomialBoundsN.getLowerBound(k, theta, stdDev, false);
    println("K=" + k + ", Theta=" + theta + ", SD=" + stdDev);
    println("UB:  " + ub);
    println("Est: " + est);
    println("LB:  " + lb);
    println("");
}

