@Test
public void checkLoadMemory() {
    printf("%8s %8s %10s %35s\n", "vIn", "c", "Flavor", "Format");
    CpcSketch sk = new CpcSketch(lgK);
    int k = 1 << lgK;
    //EMPTY_MERGED
    updateStateUnion(sk);
    //SPARSE
    sk.update(++vIn);
    updateStateUnion(sk);
    //HYBRID
    while ((sk.numCoupons << 5) < (3L * k)) {
        sk.update(++vIn);
    }
    updateStateUnion(sk);
    //PINNED
    while ((sk.numCoupons << 1) < k) {
        sk.update(++vIn);
    }
    //here
    updateStateUnion(sk);
    //SLIDING
    while ((sk.numCoupons << 3) < (27L * k)) {
        sk.update(++vIn);
    }
    updateStateUnion(sk);
}

@Test
public void checkToString() {
    CpcSketch sketch = new CpcSketch(10);
