    println(state.toString());
    sketch.update(0);
    state = CompressedState.compress(sketch);
    println(CompressedState.toString(state, true));
    for (int i = 1; i < 600; i++) {
        sketch.update(i);
    }
    state = CompressedState.compress(sketch);
    println(CompressedState.toString(state, true));
}

