@Test
public void checkEmptiesNulls() {
    long seed = 123;
    long[] hashOut = new long[2];
    Memory mem = Memory.wrap(new long[0]);
    //mem empty
    long hash0 = MurmurHash3v2.hash(mem, 0, 0, seed, hashOut)[0];
    mem = null;
    //mem null
    assertEquals(MurmurHash3v2.hash(mem, 0, 0, seed, hashOut)[0], hash0);
    String s = "";
    //string empty
    assertEquals(MurmurHash3v2.hash(s, seed, hashOut)[0], hash0);
    s = null;
    //string null
