    for (int i = k / 2; i < (k + (k / 2)); i++) {
        //overlap is k/2
        bHT.update(i);
    }
    CompactSketch bC = bHT.compact(false, null);
    CompactSketch bO = bHT.compact(true, null);
    CompactSketch res;
    AnotB aNb;
