@Test
public void checkPrimitiveUpdates() {
    int k = 32;
    Union union = Sketches.setOperationBuilder().setNominalEntries(k).buildUnion();
    //#1 long
    union.update(1L);
    //#2 double
    union.update(1.5);
    union.update(0.0);
    //#3 double
    union.update(-0.0);
    String s = null;
    //null string
    union.update(s);
    s = "";
    //empty string
    union.update(s);
    s = "String";
    //#4 actual string
    union.update(s);
    byte[] byteArr = null;
    //null byte[]
    union.update(byteArr);
    byteArr = new byte[0];
    //empty byte[]
    union.update(byteArr);
    byteArr = "Byte Array".getBytes(UTF_8);
    //#5 actual byte[]
    union.update(byteArr);
    char[] charArr = null;
    //null char[]
    union.update(charArr);
    charArr = new char[0];
    //empty char[]
    union.update(charArr);
    charArr = "String".toCharArray();
    //#6 actual char[]
    union.update(charArr);
    int[] intArr = null;
    //null int[]
    union.update(intArr);
    intArr = new int[0];
    //empty int[]
    union.update(intArr);
    int[] intArr2 = { 1, 2, 3, 4, 5 };
    //#7 actual int[]
    union.update(intArr2);
    long[] longArr = null;
    //null long[]
    union.update(longArr);
    longArr = new long[0];
    //empty long[]
    union.update(longArr);
    long[] longArr2 = { 6, 7, 8, 9 };
    //#8 actual long[]
    union.update(longArr2);
    CompactSketch comp = union.getResult();
    double est = comp.getEstimate();
    boolean empty = comp.isEmpty();
    assertEquals(est, 8.0, 0.0);
    assertFalse(empty);
}

