@Test
public void checkGetCurrentBytes() {
    int k = 64;
    int lowQSPreLongs = Family.QUICKSELECT.getMinPreLongs();
    int lowCompPreLongs = Family.COMPACT.getMinPreLongs();
    // QS Sketch
    UpdateSketch sketch = UpdateSketch.builder().setNominalEntries(k).build();
    assertEquals(sketch.getCurrentPreambleLongs(false), lowQSPreLongs);
    //compact form
    assertEquals(sketch.getCurrentPreambleLongs(true), 1);
    assertEquals(sketch.getCurrentDataLongs(false), k * 2);
    //compact form
    assertEquals(sketch.getCurrentDataLongs(true), 0);
    assertEquals(sketch.getCurrentBytes(false), (k * 2 * 8) + (lowQSPreLongs << 3));
    assertEquals(sketch.getCurrentBytes(true), lowCompPreLongs << 3);
    CompactSketch compSk = sketch.compact(false, null);
    assertEquals(compSk.getCurrentBytes(true), 8);
    assertEquals(compSk.getCurrentBytes(false), 8);
    int compPreLongs = Sketch.computeCompactPreLongs(sketch.getThetaLong(), sketch.isEmpty(), sketch.getRetainedEntries(true));
    assertEquals(compPreLongs, 1);
    for (int i = 0; i < k; i++) {
        sketch.update(i);
    }
    assertEquals(sketch.getCurrentPreambleLongs(false), lowQSPreLongs);
    //compact form
    assertEquals(sketch.getCurrentPreambleLongs(true), 2);
    assertEquals(sketch.getCurrentDataLongs(false), k * 2);
    //compact form
    assertEquals(sketch.getCurrentDataLongs(true), k);
    assertEquals(sketch.getCurrentBytes(false), (k * 2 * 8) + (lowQSPreLongs << 3));
    //compact form  //FAILS HERE
    assertEquals(sketch.getCurrentBytes(true), (k * 8) + (2 * 8));
    compPreLongs = Sketch.computeCompactPreLongs(sketch.getThetaLong(), sketch.isEmpty(), sketch.getRetainedEntries(true));
    assertEquals(compPreLongs, 2);
    for (int i = k; i < (2 * k); i++) {
        //go estimation mode
        sketch.update(i);
    }
    int curCount = sketch.getRetainedEntries(true);
    assertEquals(sketch.getCurrentPreambleLongs(false), lowQSPreLongs);
    //compact form
    assertEquals(sketch.getCurrentPreambleLongs(true), 3);
    assertEquals(sketch.getCurrentDataLongs(false), k * 2);
    //compact form
    assertEquals(sketch.getCurrentDataLongs(true), curCount);
    assertEquals(sketch.getCurrentBytes(false), (k * 2 * 8) + (lowQSPreLongs << 3));
    //compact form
    assertEquals(sketch.getCurrentBytes(true), (curCount * 8) + (3 * 8));
    compPreLongs = Sketch.computeCompactPreLongs(sketch.getThetaLong(), sketch.isEmpty(), sketch.getRetainedEntries(true));
    assertEquals(compPreLongs, 3);
    for (int i = 0; i < 3; i++) {
        int maxCompBytes = Sketch.getMaxCompactSketchBytes(i);
        assertEquals(maxCompBytes, (Family.COMPACT.getMaxPreLongs() << 3) + (i * 8));
    }
}

