public //  unless the hash function and the seed are the same
void sampling() {
    float samplingProbability = 0.001f;
    ArrayOfDoublesUpdatableSketch sketch = new ArrayOfDoublesUpdatableSketchBuilder().setSamplingProbability(samplingProbability).build(WritableMemory.wrap(new byte[1000000]));
    sketch.update("a", new double[] { 1.0 });
